import json
import sys
from pathlib import Path


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        sys.exit(1)

    target_dir = Path(sys.argv[1])

    if not target_dir.is_dir():
        print(f"error: directory not found: {target_dir}", file=sys.stderr)
        sys.exit(1)

    values = []
    for path in sorted(target_dir.glob("*.json")):
        if not path.is_file():
            continue
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and "cost_usd" in data:
            values.append(data["cost_usd"])

    if not values:
        print(f"error: no cost_usd values found in {target_dir}", file=sys.stderr)
        sys.exit(1)

    total = sum(values)
    mean = total / len(values)

    summary = {"total": total, "mean": mean}

    with open("summary.json", "w", encoding="utf-8") as f:
        json.dump(summary, f)


if __name__ == "__main__":
    main()
